    if (addr == 0x0400000A) return ctx->bg1cnt;
    if (addr == 0x0400000C) return ctx->bg2cnt;
    if (addr == 0x0400000E) return ctx->bg3cnt;
    if (addr == 0x04000130) return ctx->keyinput ? ctx->keyinput : 0x03FF;
